  public sealed class UpdateInstallation {public string Version{get;set;}public string Label{get;set;}public string Directory{get;set;}public string File{get;set;}public string Sha256{get;set;}public string PackageSha256{get;set;}}
  public sealed class UpdatePreferences {public bool CheckOnStart{get;set;}public bool AutoInstallComponents{get;set;}public Dictionary<string,string> Skipped{get;set;}public Dictionary<string,UpdateInstallation> Installed{get;set;}public UpdatePreferences(){CheckOnStart=true;AutoInstallComponents=false;Skipped=new Dictionary<string,string>();Installed=new Dictionary<string,UpdateInstallation>();}}
  public sealed class UpdateItem {
    public string Id,Name,Group,Current,Version,Status,Url,Kind,Text,Snapshot,AppliedVersion,Detail,CurrentLabel,VersionLabel,RouteId,PresetName;
    public Dictionary<string,string> SourceTexts;public UpdateAsset Asset;public EnginePackage Package;public bool Available,Ignored;
    public bool IsCurrent{get{return !Available&&!String.IsNullOrEmpty(Status)&&Status.IndexOf("актуал",StringComparison.OrdinalIgnoreCase)>=0&&!Status.StartsWith("Не удалось");}}
    public string DisplayStatus{get{return Ignored?"Версия пропущена":IsCurrent?"Актуально":Status;}}
    public string Fingerprint{get{return Version+"|"+(Asset==null?Package==null?"":Package.Sha256:Asset.digest??"");}}
  }
  public sealed class AppUpdates : IDisposable {
    readonly NetworkCore core;readonly string root;readonly Func<string,Task<string>> fetch;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=10485760};readonly CancellationTokenSource lifetime=new CancellationTokenSource();readonly Dictionary<string,Task<UpdateRelease[]>> releaseCache=new Dictionary<string,Task<UpdateRelease[]>>();
    public UpdatePreferences Preferences{get;private set;}public List<UpdateItem> Items{get;private set;}public DateTime CheckedAt{get;private set;}public bool Checking{get;private set;}public bool Installing{get;private set;}public int Progress{get;private set;}public string Activity{get;private set;}
    public string PreferencesError{get;private set;}
    public AppUpdates(NetworkCore network,Func<string,Task<string>> download=null){core=network;root=Path.Combine(core.DataRoot,"updates");var source=download??core.DownloadRemoteTextAsync;fetch=url=>RetryDownload(url,source,lifetime.Token);try{ReloadPreferences();}catch(IOException){Preferences=new UpdatePreferences{CheckOnStart=false};}Items=new List<UpdateItem>();}
    public static async Task<string> RetryDownload(string url,Func<string,Task<string>> download,CancellationToken token,Func<int,Task> pause=null){for(int attempt=0;attempt<3;attempt++){token.ThrowIfCancellationRequested();try{return await download(url);}catch(OperationCanceledException){throw;}catch(Exception ex){if(attempt==2||!Regex.IsMatch(ex.Message??"",@"curl:\s*\((6|28)\)|Resolving timed out|Could not resolve host",RegexOptions.IgnoreCase))throw;}if(pause!=null)await pause((attempt+1)*1000);else await Task.Delay((attempt+1)*1000,token);}throw new InvalidOperationException("Источник не ответил.");}
    static UpdatePreferences ReadPreferencesStrict(string dataRoot){string path=Path.Combine(dataRoot,"updates","preferences.json");string text;try{text=File.ReadAllText(path);}catch(FileNotFoundException){return new UpdatePreferences();}catch(DirectoryNotFoundException){return new UpdatePreferences();}if(text.Length>10485760)throw new FormatException("Настройки обновлений слишком большие.");var p=new JavaScriptSerializer{MaxJsonLength=10485760}.Deserialize<UpdatePreferences>(text);if(p==null||p.Skipped==null||p.Installed==null||p.Installed.Any(item=>item.Value==null))throw new FormatException("Некорректные настройки обновлений.");return p;}
    public static UpdatePreferences ReadPreferences(string dataRoot){try{return ReadPreferencesStrict(dataRoot);}catch(IOException){}catch(UnauthorizedAccessException){}catch(ArgumentException){}catch(InvalidOperationException){}catch(FormatException){}return new UpdatePreferences();}
    public void ReloadPreferences(){if(Checking||Installing)throw new InvalidOperationException("Дождитесь текущей операции.");try{var loaded=ReadPreferencesStrict(core.DataRoot);Preferences=loaded;PreferencesError=null;}catch(Exception ex){if(!(ex is IOException)&&!(ex is UnauthorizedAccessException)&&!(ex is ArgumentException)&&!(ex is InvalidOperationException)&&!(ex is FormatException))throw;PreferencesError="Настройки обновлений не прочитаны. Исходный файл сохранён. Восстановите его из резервной копии и повторите чтение.";throw new IOException(PreferencesError,ex);}}
    void EnsurePreferencesReadable(){if(PreferencesError!=null)throw new IOException(PreferencesError);}
    public static void AtomicText(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".new-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temp,text,new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,path+".previous");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
    public void Save(){EnsurePreferencesReadable();AtomicText(Path.Combine(root,"preferences.json"),json.Serialize(Preferences));}
    public void Skip(IEnumerable<UpdateItem> items){EnsurePreferencesReadable();var previous=new Dictionary<string,string>(Preferences.Skipped);try{foreach(var row in items.Where(x=>x.Available))Preferences.Skipped[row.Id]=row.Fingerprint;Save();}catch{Preferences.Skipped=previous;throw;}MarkIgnored();}
    public void MarkIgnored(){foreach(var row in Items){string version;row.Ignored=Preferences.Skipped.TryGetValue(row.Id,out version)&&version==row.Fingerprint;}}
    public static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
    public static string HashFile(string file){using(var s=File.OpenRead(file))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
    public static string TextVersion(string text){return Hash(Encoding.UTF8.GetBytes((text??"").Replace("\r\n","\n").Trim().TrimStart('\uFEFF')));}
    public static string ListVersion(string text){var parsed=RouteCompiler.Parse(text??"");return TextVersion(String.Join("\n",parsed.OrderBy(p=>p.Key,StringComparer.Ordinal).SelectMany(p=>p.Value.Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(v=>v,StringComparer.OrdinalIgnoreCase).Select(v=>p.Key+":"+v.ToLowerInvariant()))));}
    public static int CompareVersion(string a,string b){var x=Regex.Matches(a??"",@"\d+").Cast<Match>().Select(m=>Int64.Parse(m.Value)).ToArray();var y=Regex.Matches(b??"",@"\d+").Cast<Match>().Select(m=>Int64.Parse(m.Value)).ToArray();for(int i=0;i<Math.Max(x.Length,y.Length);i++){int c=(i<x.Length?x[i]:0).CompareTo(i<y.Length?y[i]:0);if(c!=0)return c;}return 0;}
    public static UpdateRelease Latest(IEnumerable<UpdateRelease> releases,Func<UpdateRelease,bool> filter){return releases.Where(r=>!r.draft&&!r.prerelease&&filter(r)).OrderByDescending(r=>r.tag_name,Comparer<string>.Create(CompareVersion)).ThenByDescending(r=>r.published_at).FirstOrDefault();}
    public static bool SafeAsset(UpdateAsset asset,string repository){Uri u;return asset!=null&&asset.size>0&&asset.size<=160000000&&Regex.IsMatch(asset.digest??"",@"^sha256:[a-fA-F0-9]{64}$")&&Uri.TryCreate(asset.browser_download_url,UriKind.Absolute,out u)&&u.Scheme=="https"&&u.Host=="github.com"&&u.AbsolutePath.StartsWith("/"+repository+"/releases/download/",StringComparison.Ordinal)&&u.UserInfo.Length==0;}
    public static string ActiveFile(string dataRoot,string id,string fallback){var p=ReadPreferences(dataRoot);UpdateInstallation item;if(!p.Installed.TryGetValue(id,out item))return fallback;try{string folder=Path.GetFullPath(Path.Combine(dataRoot,"updates","installed"))+Path.DirectorySeparatorChar;string path=Path.GetFullPath(Path.Combine(item.Directory,item.File));if(!path.StartsWith(folder,StringComparison.OrdinalIgnoreCase)&&String.Equals(Path.GetFileName(Path.GetFullPath(dataRoot).TrimEnd(Path.DirectorySeparatorChar)),"mcrf",StringComparison.OrdinalIgnoreCase)){string legacy=Path.GetFullPath(Path.Combine(dataRoot,"..","splify-win","updates","installed"))+Path.DirectorySeparatorChar;if(path.StartsWith(legacy,StringComparison.OrdinalIgnoreCase))path=Path.GetFullPath(Path.Combine(folder,path.Substring(legacy.Length)));}return path.StartsWith(folder,StringComparison.OrdinalIgnoreCase)&&File.Exists(path)&&HashFile(path)==item.Sha256?path:fallback;}catch(IOException){return fallback;}catch(ArgumentException){return fallback;}catch(UnauthorizedAccessException){return fallback;}}
    static string NumericLabel(string version){if(String.IsNullOrWhiteSpace(version))return "—";return version.StartsWith("engines-")?version.Substring(8).Replace('-','.'):Regex.Replace(version,@"^(?:v|ZapretOzz-v)","");}
    string CurrentLabel(string id,string fallback){UpdateInstallation item;return Preferences.Installed.TryGetValue(id,out item)&&ActiveFile(core.DataRoot,id,"")!=""?item.Label??(Regex.IsMatch(item.Version??"",@"^[a-f0-9]{64}$")?"Снимок источника":NumericLabel(item.Version)):fallback;}
    static RoutePreset PresetByName(string name){return RoutePresets.Resolve(name);}
    static string PresetBaseline(RouteList route,string name){if(String.IsNullOrWhiteSpace(name))return null;string text;if(route.PresetEntries!=null&&route.PresetEntries.TryGetValue(name,out text))return text;var preset=PresetByName(name);if(preset==null)return null;if(route.PresetEntries!=null){var entry=route.PresetEntries.FirstOrDefault(p=>PresetByName(p.Key)==preset);if(entry.Value!=null)return entry.Value;}var texts=PresetStorage.Sources(preset).Select(PresetStorage.BundledText).ToArray();return texts.Any(t=>t==null)?null:String.Join("\n",texts);}
    public static string ReplacePresetSlice(RouteList route,string name,string previous,string next){
      var old=RouteCompiler.Parse(previous);var all=RouteCompiler.Parse(route.Text);var added=RouteCompiler.Parse(next);var other=RouteCompiler.Parse(String.Join("\n",(route.PresetEntries??new Dictionary<string,string>()).Where(p=>!String.Equals(p.Key,name,StringComparison.OrdinalIgnoreCase)&&(PresetByName(name)==null||PresetByName(p.Key)!=PresetByName(name))).Select(p=>p.Value))+"\n"+(route.CustomText??""));
      var lines=new List<string>();foreach(string key in all.Keys){var values=all[key].Where(v=>!old[key].Contains(v,StringComparer.OrdinalIgnoreCase)||other[key].Contains(v,StringComparer.OrdinalIgnoreCase)).Concat(added[key]).Distinct(StringComparer.OrdinalIgnoreCase);foreach(string value in values)lines.Add(key=="process_name"?"app:"+value:key=="process_path"?"path:"+value:key=="domain"?"DOMAIN,"+value:value);}
      lines.InsertRange(0,(route.Text??"").Split('\n').Where(l=>l.TrimStart().StartsWith("#")));return String.Join("\n",lines);
    }
    static string SafeListVersion(string text){try{return ListVersion(text);}catch(FormatException){return TextVersion(text);}}
    static string CountLabel(string text){try{return RouteCompiler.Parse(text??"").Values.Sum(v=>v.Count)+" записей";}catch(FormatException){return "Проверьте записи";}}
    static int UpdateOrder(UpdateItem row){return row.Id=="app"?0:row.Group=="Движки"?1:row.Group=="Дополнительные движки"?2:row.Group=="Конфиги Zapret"?3:4;}
    string Current(string id,string fallback){UpdateInstallation p;return Preferences.Installed.TryGetValue(id,out p)&&ActiveFile(core.DataRoot,id,"")!=""?p.Version:fallback;}
    Task<UpdateRelease[]> Releases(string repo){lock(releaseCache){Task<UpdateRelease[]> data;if(!releaseCache.TryGetValue(repo,out data)){data=ReadReleases(repo);releaseCache[repo]=data;}return data;}}
    async Task<UpdateRelease[]> ReadReleases(string repo){string data=await fetch("https://api.github.com/repos/"+repo+"/releases?per_page=100");lifetime.Token.ThrowIfCancellationRequested();return json.Deserialize<UpdateRelease[]>(data);}
    string EmbeddedText(string suffix){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("SplifyWin.Zapret."+suffix))using(var reader=new StreamReader(s))return reader.ReadToEnd();}
