      foreach(var list in state.Lists.Where(l=>RouteSources.Urls(l).Length>0)){var l=list;string metadataIssue=RoutePresets.MetadataIssue(l);if(metadataIssue!=null){lock(result){result.RemoveAll(i=>i.RouteId==l.Id||i.Id=="list:"+l.Id);result.Add(new UpdateItem{Id="list-metadata:"+l.Id,RouteId=l.Id,Name=ZapretStrategy.CleanLabel(l.Name)+" · метаданные",Group="Списки маршрутизации",Kind="notice",Status="Метаданные пресетов повреждены",Detail=metadataIssue});}continue;}var names=RoutePresets.AttachedNames(l).Where(n=>PresetBaseline(l,n)!=null&&PresetByName(n)!=null&&PresetStorage.Sources(PresetByName(n)).Length>0).GroupBy(n=>PresetByName(n).Name,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToArray();
        lock(result){result.RemoveAll(i=>names.Length>0&&i.Id=="list:"+l.Id||i.RouteId==l.Id&&i.Kind=="link"&&i.PresetName!=null&&PresetByName(i.PresetName)!=null);}
        var unresolved=RoutePresets.AttachedNames(l).Where(n=>PresetByName(n)==null||PresetBaseline(l,n)==null).ToArray();if(unresolved.Length>0){lock(result){result.RemoveAll(i=>i.Id=="list:"+l.Id||i.RouteId==l.Id&&i.PresetName!=null&&unresolved.Contains(i.PresetName));result.Add(new UpdateItem{Id="list-presets:"+l.Id,RouteId=l.Id,Name=ZapretStrategy.CleanLabel(l.Name)+" · пресеты",Group="Списки маршрутизации",Kind="notice",Status="Состав пресетов не определён",Detail="Не проверено пресетов: "+unresolved.Length+". Каталог или сохранённый снимок недоступен. Автоматическая замена всего списка заблокирована; записи и источники сохранены."});}if(names.Length==0)continue;}
        bool localOutside=l.BuiltinPreset!="outside-ru"&&(l.PresetNames??new List<string>()).Any(n=>n==OutsideRussiaPreset.Name||n=="Все кроме РФ");
        var covered=new HashSet<string>(names.SelectMany(n=>PresetStorage.Sources(PresetByName(n))),StringComparer.Ordinal);var uncovered=RouteSources.Urls(l).Where(u=>!covered.Contains(u)).ToArray();
        lock(result){result.RemoveAll(i=>i.RouteId==l.Id&&i.PresetName!=null&&PresetByName(i.PresetName)!=null&&PresetByName(i.PresetName).OutsideRussia);if((names.Length>0||localOutside)&&uncovered.Length>0)result.Add(new UpdateItem{Id="list-sources:"+l.Id,RouteId=l.Id,Name=ZapretStrategy.CleanLabel(l.Name)+" · источники",Group="Списки маршрутизации",Kind="notice",Status="Отдельные URL не проверены",Detail="Не проверено дополнительных URL: "+uncovered.Length+". Нет отдельного снимка их записей: автоматическая замена могла бы удалить ручные записи или пресеты. Для обновления этих URL вынесите их в отдельный список. Сохранённые записи не изменены."});}
        if(localOutside&&names.Length==0)continue;
        if(names.Length>0){foreach(string presetName in names){string name=presetName,baseline=PresetBaseline(l,name);var preset=PresetByName(name);operations.Add(check(new UpdateItem{Id="preset:"+l.Id+":"+TextVersion(name).Substring(0,12),RouteId=l.Id,PresetName=name,Name=l.Name==name?name:l.Name+" · "+name,Group="Списки маршрутизации",Current=SafeListVersion(baseline),CurrentLabel=CountLabel(baseline),Snapshot=baseline,Url=String.Join("\n",PresetStorage.Sources(preset)),Kind="preset"},async row=>{var urls=PresetStorage.Sources(preset);var texts=await Task.WhenAll(urls.Select(url=>fetch(url)));row.SourceTexts=urls.Select((url,i)=>new{url,text=texts[i]}).ToDictionary(p=>p.url,p=>p.text);row.Text=String.Join("\n",texts);ValidateList(row.Text,new RouteList{MatchMode="addresses"});ValidateList(ReplacePresetSlice(l,name,baseline,row.Text),l);row.Version=ListVersion(row.Text);row.VersionLabel=CountLabel(row.Text);row.Available=row.Version!=row.Current;row.Status=row.Available?"Обновление пресета · ваши записи сохранятся":"Пресет актуален";}));}continue;}
        operations.Add(check(new UpdateItem{Id="list:"+l.Id,Name=ZapretStrategy.CleanLabel(l.Name),Group="Списки маршрутизации",Current=SafeListVersion(l.Text),CurrentLabel=CountLabel(l.Text),Snapshot=l.Text,Url=RouteSources.Identity(l),Kind="list"},async row=>{row.Text=RouteSources.UpdatedText(l,String.Join("\n",await Task.WhenAll(RouteSources.Urls(l).Select(url=>fetch(url)))));ValidateList(row.Text,l);row.Version=ListVersion(row.Text);row.VersionLabel=CountLabel(row.Text);row.Available=row.Version!=row.Current;row.Status=row.Available?"Обновление списка":"Список актуален";}));
      }
      await Task.WhenAll(operations);lifetime.Token.ThrowIfCancellationRequested();Items=result.Where(i=>i.Kind!="catalog").OrderBy(UpdateOrder).ThenBy(i=>i.Id=="app"?"":i.Name).ToList();CheckedAt=DateTime.Now;MarkIgnored();Activity="Проверено · "+Items.Count(i=>i.Available)+" обновлений"+(Items.Any(i=>i.Kind=="notice")?" · часть источников не проверена":Items.Any(i=>i.Detail!=null)?" · некоторые источники недоступны":"");}finally{Checking=false;gate.Dispose();}
    }
    void Release(UpdateItem row,UpdateRelease release,string assetSuffix,string repo){row.Version=release.tag_name;row.Url=release.html_url;row.Asset=(release.assets??new List<UpdateAsset>()).FirstOrDefault(a=>a.name.EndsWith(assetSuffix,StringComparison.OrdinalIgnoreCase));if(row.Id=="app")row.Asset=(release.assets??new List<UpdateAsset>()).FirstOrDefault(a=>a.name==AppRuntime.PackageName);row.Available=CompareVersion(row.Version,row.Current)>0;row.Status=!row.Available?"Актуально":SafeAsset(row.Asset,repo)?"Доступно обновление · "+(row.Asset.size/1000000d).ToString("0.00")+" МБ":"Нет малого пакета приложения · откройте релиз";if(row.Available&&!SafeAsset(row.Asset,repo))row.Kind="link";if(row.Id=="app"&&row.Available&&row.Kind=="app"){UpdateInstallation staged;if(Preferences.Installed.TryGetValue("app-stage",out staged)&&staged.Version==row.Version&&staged.PackageSha256==row.Asset.digest.Substring(7).ToLowerInvariant())row.AppliedVersion=ActiveFile(core.DataRoot,"app-stage",null);} }
    async Task StrategyProvenance(UpdateItem row,string file){
      var releases=(await Releases("StressOzz/Zapret-Manager")).Where(r=>!r.draft&&!r.prerelease&&Regex.IsMatch(r.tag_name??"",@"^ZapretOzz-v\d+(?:\.\d+)+$")).OrderByDescending(r=>r.published_at).Take(8).ToArray();string newest=null;
      foreach(var release in releases){try{string released=await fetch("https://raw.githubusercontent.com/StressOzz/Zapret-Manager/"+Uri.EscapeDataString(release.tag_name)+"/"+file);ValidateStrategies(row.Id,released);string version=NumericLabel(release.tag_name);if(newest==null)newest=version;if(TextVersion(released)==row.Current)row.CurrentLabel=version;if(TextVersion(released)==row.Version){row.VersionLabel=version;break;}}catch(OperationCanceledException){throw;}catch(Exception){/* Branch snapshots do not necessarily belong to a numbered release. */}}
      if(row.VersionLabel=="Снимок источника"){row.VersionLabel=newest==null?"Без номера релиза":"После "+newest;row.Status+=(row.Available?" · источник без отдельного релиза":"");}
    }
    public static void ValidateStrategies(string id,string text){if(String.IsNullOrWhiteSpace(text)||text.Length>2000000||!text.Contains("--dpi-desync=")||!(id=="v-config"?Regex.IsMatch(text,@"(?m)^# v\d+"):Regex.IsMatch(text,@"(?m)^#Yv\d+")))throw new InvalidDataException("Источник не содержит ожидаемых стратегий");}
    public static void ValidateList(string text,RouteList original){if(String.IsNullOrWhiteSpace(text)||text.Length>64*1024*1024||text.TrimStart().StartsWith("<"))throw new InvalidDataException("Пустой список или HTML вместо списка");var copy=new RouteList{Text=text,MatchMode=original.MatchMode};var parsed=RouteCompiler.Parse(text);if(parsed.Values.Sum(x=>x.Count)==0)throw new InvalidDataException("Список не содержит адресов / приложений");RouteCompiler.Compile(copy,"direct");if(ZapretRoutes.IsZapret(original))ZapretScope.Validate(copy);}
    public async Task Apply(UpdateItem row,ClientState state,StateStore store){EnsurePreferencesReadable();if(Installing||Checking)throw new InvalidOperationException("Дождитесь текущей операции");if(!Items.Contains(row)||(!row.Available&&!(row.Kind=="optional"&&!core.Engines.Installed(row.Package.Id)))||row.Kind=="link"||row.Kind=="catalog"||row.Kind=="notice")throw new InvalidOperationException("Нет устанавливаемого обновления");Installing=true;Progress=0;Activity="Подготовка: "+row.Name;string staging=null;try{
        if(row.Kind=="preset"){var list=state.Lists.FirstOrDefault(l=>l.Id==row.RouteId);if(list==null||RoutePresets.MetadataIssue(list)!=null||!RoutePresets.AttachedNames(list).Contains(row.PresetName,StringComparer.OrdinalIgnoreCase)||ListVersion(PresetBaseline(list,row.PresetName))!=ListVersion(row.Snapshot))throw new InvalidOperationException("Пресет изменён после проверки. Проверьте обновления заново.");string next=ReplacePresetSlice(list,row.PresetName,row.Snapshot,row.Text);ValidateList(next,list);AtomicText(Path.Combine(root,"backups",list.Id+"-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmssfff")+".json"),new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue}.Serialize(list));string old=list.Text;var oldMap=list.PresetEntries;list.Text=next;list.PresetEntries=new Dictionary<string,string>(oldMap??new Dictionary<string,string>());foreach(var key in list.PresetEntries.Keys.Where(k=>PresetByName(row.PresetName)!=null&&PresetByName(k)==PresetByName(row.PresetName)).ToArray())list.PresetEntries.Remove(key);list.PresetEntries[row.PresetName]=row.Text;var priorCache=(row.SourceTexts??new Dictionary<string,string>()).ToDictionary(p=>p.Key,p=>PresetStorage.Read(core.DataRoot,p.Key));try{if(row.SourceTexts!=null)PresetStorage.StoreSnapshots(core.DataRoot,row.SourceTexts);store.Save(state);}catch{list.Text=old;list.PresetEntries=oldMap;if(priorCache.Count>0)PresetStorage.StoreSnapshots(core.DataRoot,priorCache);throw;}}
        else if(row.Kind=="list"){var list=state.Lists.FirstOrDefault(l=>"list:"+l.Id==row.Id);if(list==null||RoutePresets.MetadataIssue(list)!=null||RouteSources.Identity(list)!=row.Url||TextVersion(list.Text)!=TextVersion(row.Snapshot))throw new InvalidOperationException("Список изменён после проверки. Проверьте обновления заново");ValidateList(row.Text,list);AtomicText(Path.Combine(root,"backups",list.Id+"-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmssfff")+".txt"),list.Text);string old=list.Text;list.Text=row.Text;try{store.Save(state);}catch{list.Text=old;throw;}}
        else if(row.Kind=="mcrf-core"){CoreEngineUpdates.ValidatePackage(row.Package);string dir=Path.Combine(root,"installed",row.Id+"-"+Guid.NewGuid().ToString("N"));staging=dir;Directory.CreateDirectory(dir);string archive=Path.Combine(dir,"download.bin");await Download(new UpdateAsset{browser_download_url=row.Package.Url,size=row.Package.Size,digest="sha256:"+row.Package.Sha256},archive,lifetime.Token);CoreEngineUpdates.Extract(archive,dir,row.Package);string file=CoreEngineUpdates.MainFile(row.Id);ValidatePe(Path.Combine(dir,file));Activate(row,dir,file);staging=null;}
        else if(row.Kind=="optional"){await core.Engines.InstallUpdate(row.Package);}
        else if(row.Kind=="text"){ValidateStrategies(row.Id,row.Text);string dir=Path.Combine(root,"installed",row.Id+"-"+row.Version.Substring(0,12));string file=row.Id=="v-config"?"v.md":"youtube.md";AtomicText(Path.Combine(dir,file),row.Text);Activate(row,dir,file);}
        else{string repository=row.Id=="app"?"vnenapravo7-source/mcrf":row.Id=="telegram"?"y0sy4/telegram-proxy":row.Id=="warp"?"vernette/warpscout":row.Id=="zapret"||row.Id=="flowseal-config"?"Flowseal/zapret-discord-youtube":"";if(repository.Length==0||!SafeAsset(row.Asset,repository))throw new InvalidDataException("Непроверяемый источник обновления");string dir=Path.Combine(root,"installed",row.Id+"-"+Guid.NewGuid().ToString("N"));staging=dir;Directory.CreateDirectory(dir);string archive=Path.Combine(dir,"download.bin");await Download(row.Asset,archive,lifetime.Token);string file=row.Kind=="app"?"mcrf.exe":row.Kind=="exe"?"tgws.exe":row.Kind=="warp"?"warpscout.exe":"flowseal.zip";
          if(row.Kind=="app"){if(row.Asset.name!=AppRuntime.PackageName)throw new InvalidDataException("Нужен малый пакет приложения");var module=AppRuntime.Extract(archive,dir);if(CompareVersion(module.Version,row.Version)!=0)throw new InvalidDataException("Версия пакета не совпала с релизом");await EnsureRuntime(module,row.Asset);File.Delete(archive);}else if(row.Kind=="exe"){ValidatePe(archive);File.Move(archive,Path.Combine(dir,file));}
          else if(row.Kind=="warp"){ExtractSelected(archive,dir,new[]{"warpscout.exe","LICENSE"});ValidatePe(Path.Combine(dir,file));File.Delete(archive);}
          else{File.Move(archive,Path.Combine(dir,file));ValidateFlowseal(Path.Combine(dir,file));if(row.Kind=="zapret")ExtractZapret(Path.Combine(dir,file),dir);}
          if(row.Kind=="app"){var staged=new UpdateItem{Id="app-stage",Version=row.Version,Asset=row.Asset};Activate(staged,dir,file);row.AppliedVersion=Path.Combine(dir,file);row.Status="Скачано и проверено · нажмите «Установить и перезапустить»";}
          else Activate(row,dir,file);staging=null;
        }
        if(row.Kind!="app"){row.Current=row.Version;row.CurrentLabel=row.VersionLabel;row.Available=false;row.Status=row.Kind=="preset"||row.Kind=="list"?"Обновлено · записи сохранены":"Обновлено";}Progress=100;Activity="Готово: "+row.Name;
      }catch(Exception){Activity="Обновление не применено: "+row.Name;throw;}finally{Installing=false;if(staging!=null){string prefix=Path.GetFullPath(Path.Combine(root,"installed"))+Path.DirectorySeparatorChar;if(!Path.GetFullPath(staging).StartsWith(prefix,StringComparison.OrdinalIgnoreCase)||!Regex.IsMatch(Path.GetFileName(staging),@"-[a-f0-9]{32}$"))throw new IOException("Небезопасный путь временного обновления");try{if(Directory.Exists(staging))Directory.Delete(staging,true);}catch(IOException){}catch(UnauthorizedAccessException){}}}
    }
    public void InstallApplication(UpdateItem row){EnsurePreferencesReadable();UpdateInstallation staged;if(Installing||Checking||row==null||!Items.Contains(row)||row.Kind!="app"||!SafeAsset(row.Asset,"vnenapravo7-source/mcrf")||!Preferences.Installed.TryGetValue("app-stage",out staged)||staged.PackageSha256!=row.Asset.digest.Substring(7).ToLowerInvariant()||String.IsNullOrEmpty(row.AppliedVersion)||HashFile(row.AppliedVersion)!=staged.Sha256)throw new InvalidOperationException("Сначала скачайте и проверьте обновление");var module=AppRuntime.ReadModule(File.ReadAllText(Path.Combine(Path.GetDirectoryName(row.AppliedVersion),"module.json")));if(module.Hash!=staged.Sha256)throw new InvalidDataException("Изменились данные пакета");AppRuntime.Activate(core.DataRoot,module);AppRuntime.Restart(core.DataRoot);}
    void Activate(UpdateItem row,string dir,string file){UpdateInstallation previous;Preferences.Installed.TryGetValue(row.Id,out previous);Preferences.Installed[row.Id]=new UpdateInstallation{Version=row.Version,Label=row.VersionLabel,Directory=dir,File=file,Sha256=HashFile(Path.Combine(dir,file)),PackageSha256=row.Asset==null?null:row.Asset.digest.Substring(7).ToLowerInvariant()};try{Save();}catch{if(previous==null)Preferences.Installed.Remove(row.Id);else Preferences.Installed[row.Id]=previous;throw;}}
    async Task Download(UpdateAsset asset,string file,CancellationToken token){if(asset==null||!Regex.IsMatch(asset.digest??"",@"^sha256:[a-fA-F0-9]{64}$"))throw new InvalidDataException("Отсутствует SHA-256 пакета");var psi=new ProcessStartInfo(core.CurlExecutable,"--silent --show-error --fail --location --noproxy \"*\" --connect-timeout 10 --max-time 180 --max-filesize "+asset.size+" --proto =https --proto-redir =https --cacert "+ZapretRuntime.Quote(Path.Combine(core.DataRoot,"core","curl-ca-bundle.crt"))+" --output "+ZapretRuntime.Quote(file)+" "+ZapretRuntime.Quote(asset.browser_download_url)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=OwnedJob.Start(psi)){var output=p.StandardOutput.ReadToEndAsync();var errors=p.StandardError.ReadToEndAsync();try{while(!p.HasExited){token.ThrowIfCancellationRequested();long received=File.Exists(file)?new FileInfo(file).Length:0;if(received>asset.size)throw new InvalidDataException("Превышен размер пакета");Progress=(int)(received*90/asset.size);Activity="Загрузка: "+(received/1000000d).ToString("0.0")+" / "+(asset.size/1000000d).ToString("0.0")+" МБ";await Task.Delay(120,token);}await output;await errors;token.ThrowIfCancellationRequested();if(p.ExitCode!=0||!File.Exists(file)||new FileInfo(file).Length!=asset.size)throw new IOException("Пакет не скачан полностью · код "+p.ExitCode);Progress=95;if(HashFile(file)!=asset.digest.Substring(7).ToLowerInvariant())throw new InvalidDataException("SHA-256 не совпал. Обновление не применено");}finally{if(!p.HasExited)try{p.Kill();}catch{}}}}
    public static void ValidatePe(string path,bool managedAllowed=false){using(var s=File.OpenRead(path))using(var r=new BinaryReader(s)){if(s.Length<128||r.ReadUInt16()!=0x5A4D)throw new InvalidDataException("Файл не является Windows-программой");s.Position=60;int offset=r.ReadInt32();if(offset<64||offset>s.Length-6)throw new InvalidDataException("Повреждён PE-файл");s.Position=offset;if(r.ReadUInt32()!=0x4550)throw new InvalidDataException("Повреждён PE-файл");ushort machine=r.ReadUInt16();if(machine==0x8664)return;if(managedAllowed&&machine==0x14c){s.Position=offset+24;if(r.ReadUInt16()==0x10b&&s.Length>offset+24+96+14*8+8){s.Position=offset+24+96+14*8;if(r.ReadUInt32()!=0&&r.ReadUInt32()>=72)return;}}throw new InvalidDataException("Нужна сборка Windows x64 или .NET AnyCPU для MCRF");}}
    public static void ValidateFlowseal(string path){using(var zip=ZipFile.OpenRead(path)){if(zip.Entries.Count>1500||zip.Entries.Sum(e=>e.Length)>50000000||!zip.Entries.Any(e=>e.FullName.EndsWith("/bin/winws.exe"))||!zip.Entries.Any(e=>Path.GetFileName(e.FullName).StartsWith("general")&&e.FullName.EndsWith(".bat")))throw new InvalidDataException("Неожиданный состав Flowseal");foreach(var e in zip.Entries)SafeEntry(e);}}
    static void SafeEntry(ZipArchiveEntry e){if(e.FullName.StartsWith("/")||e.FullName.Contains("\\")||e.FullName.Contains(":")||e.FullName.Split('/').Any(p=>p=="..")||((e.ExternalAttributes>>16)&0xF000)==0xA000||e.Length>100000000)throw new InvalidDataException("Небезопасный путь в архиве");}
    public static void ExtractSelected(string archive,string destination,string[] names){using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count>1500||zip.Entries.Sum(e=>e.Length)>200000000)throw new InvalidDataException("Слишком большой архив");foreach(var name in names){var matches=zip.Entries.Where(e=>Path.GetFileName(e.FullName)==name).ToArray();if(matches.Length==0&&name=="LICENSE")continue;if(matches.Length!=1)throw new InvalidDataException("Нет однозначного файла "+name);SafeEntry(matches[0]);matches[0].ExtractToFile(Path.Combine(destination,name));}}}
    static void ExtractZapret(string archive,string directory){using(var zip=ZipFile.OpenRead(archive)){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var e in zip.Entries.Where(e=>e.FullName.Contains("/bin/")&&!String.IsNullOrEmpty(e.Name))){SafeEntry(e);if(!Regex.IsMatch(e.Name,@"^[a-zA-Z0-9_.-]+$")||!seen.Add(e.Name))throw new InvalidDataException("Неоднозначный файл Zapret");e.ExtractToFile(Path.Combine(directory,e.Name));}}ValidatePe(Path.Combine(directory,"winws.exe"));}
    async Task EnsureRuntime(AppModule module,UpdateAsset package){foreach(var r in module.Runtime.Resources){lifetime.Token.ThrowIfCancellationRequested();if(RuntimeResources.Present(core.DataRoot,r))continue;string target=RuntimeResources.PathFor(core.DataRoot,r),temp=target+"."+Guid.NewGuid().ToString("N")+".tmp";Directory.CreateDirectory(Path.GetDirectoryName(target));var asset=new UpdateAsset{name="runtime-"+r.Hash+".bin",size=r.Size,digest="sha256:"+r.Hash,browser_download_url=package.browser_download_url.Substring(0,package.browser_download_url.LastIndexOf('/')+1)+"runtime-"+r.Hash+".bin"};if(!SafeAsset(asset,"vnenapravo7-source/mcrf"))throw new InvalidDataException("Непроверяемый источник компонента");try{Activity="Компонент "+r.Name+" · "+(r.Size/1000000d).ToString("0.0")+" МБ";await Download(asset,temp,lifetime.Token);if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);}finally{if(File.Exists(temp))File.Delete(temp);}}}
    public void Dispose(){lifetime.Cancel();}
  }
